SELECT COUNT(DISTINCT a.subject_id) AS n, AVG(a.los) AS average_length_of_stay, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY a.los) AS p25, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS p75, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS p90, PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY a.los) AS p95, SUM(CASE WHEN a.discharge_location IN ('home', 'SNF/rehab/LTACH') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_of_patients_discharged_to_home_or_snp, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_of_patients_with_in_hospital_death FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id WHERE p.gender = 'M' AND p.anchor_age = 42 AND EXTRACT(YEAR FROM a.admittime) = p.anchor_year AND EXTRACT(YEAR FROM a.dischtime) = p.anchor_year + 5 AND t.eventtype = 'transfer' AND EXTRACT(YEAR FROM t.intime) BETWEEN 2015 AND 2018 AND EXTRACT(YEAR FROM t.outtime) BETWEEN 2015 AND 2018 AND (a.discharge_location IN ('home', 'SNF/rehab/LTACH') OR a.deathtime IS NOT NULL);